/**
 * Public types of @holodeck/editor-2.5d-react as released on main (882cff5),
 * copied verbatim from assets/process/tank-params.ts and assets/process/style.ts
 * there (doc comments stripped). src/public-api-compat.test.tsx checks today's
 * types against these in both directions. Do NOT edit this file to make that
 * test pass: a mismatch means the public types broke. Refresh it only when a
 * release deliberately changes these types (copy them again from that release).
 */
export type TankCap = 'dome' | 'flat';
export type TankTop = 'dome' | 'flat' | 'cone';
export type TankBottom = 'flat' | 'dish' | 'cone';
export type TankSupport = 'none' | 'legs' | 'skirt';
export type TankNozzle = 'none' | 'tangential';
export type TankParams = {
  height: number;
  radius: number;
  fill: number;
  fillColor: string;
  liquidOpacity: number;
  innerRatio: number;
  linerRatio: number;
  linerColor: string;
  windowDeg: number;
  windowYawDeg: number;
  radialSegments: number;
  bodyHeightSegments: number;
  bodyRings: number;
  bodyRingWidth: number;
  cageThreshold: number;
  wallThreshold: number;
  domeHeightSegments: number;
  domePhiDeg: number;
  domeRadiusScale: number;
  domeHeight: number;
  domeYOffset: number;
  domeThreshold: number;
  capHeightRatio: number;
  capRadiusRatio: number;
  capLidThickness: number;
  capLineWidth: number;
  bowlHeightSegments: number;
  bowlHeight: number;
  bowlYOffset: number;
  bowlThreshold: number;
  edgeColor: string;
  lineWidth: number;
  shadeMin: number;
  shadeMax: number;
  hubWhite: number;
  showCage: boolean;
  showWall: boolean;
  showLiner: boolean;
  showDome: boolean;
  showBowl: boolean;
  showInnerCage: boolean;
  showLiquid: boolean;
  shaftRadius: number;
  shaftLength: number;
  impellerSpan: number;
  impellerRadius: number;
  shoulderRatio: number;
  shoulderTopRatio: number;
  outerBowlHeight: number;
  // --- Base-vessel presets (brewery HLT / mash tun / kettle / whirlpool) ---
  top: TankTop;
  bottom: TankBottom;
  support: TankSupport;
  agitator: boolean;
  nozzle: TankNozzle;
  coneTopHeight: number;
  coneTopRatio: number;
  dishBottomHeight: number;
  coneBottomHeight: number;
  coneBottomRatio: number;
  standHeight: number;
  legRadius: number;
  legCount: number;
};
export type UnlitFinish = {
  kind: 'unlit';
  color: string;
  offset: boolean;
};
export type IsoFinish = {
  kind: 'iso';
  shadeMin: number;
  shadeMax: number;
  hubWhite: number;
  whiteHub: boolean;
  offset: boolean;
};
export type Finish = UnlitFinish | IsoFinish;
export type FinishName = 'white' | 'shaded' | 'vessel' | 'flask' | 'accent';
export type AnnotationStyle = {
  connector: string;
  connectorWidth: number;
  flow: string;
  text: string;
  icon: string;
  areaOutlineWidth: number;
  areaWall: string;
  areaWallOpacity: number;
  areaWallHeight: number;
  shadow: string;
  shadowOpacity: number;
  metaFill: string;
  metaEdge: string;
  metaText: string;
};
export type HolodeckStyle = {
  annotation?: AnnotationStyle;
  colors: {
    body: string;
    edge: string;
    areaFill: string;
    areaEdge: string;
    accent: string;
    band: string;
    bandInstanced: string;
    pipeWire: string;
    liquid: string;
    alarm: string;
    bore: string;
  };
  edges: {
    threshold: number;
    thresholds: {
      tankWall: number;
      mixerWall: number;
      elbow: number;
      pipe: number;
      valve: number;
      valveWheel: number;
      nut: number;
      westRing: number;
      steamNut: number;
      area: number;
    };
    lineWidth: number;
    wireWidth: number;
  };
  finishes: Record<FinishName, Finish> & {
    white: UnlitFinish;
    shaded: IsoFinish;
    vessel: IsoFinish;
    flask: IsoFinish;
    accent: UnlitFinish;
  };
};
